// src7/plugins/programs/ChannelBridge.ts
 179    async getCallbackUrl(spec: specModule.ProgramSpec, signal: AbortSignal): Promise<string | undefined> {
 180      //G 没登记渠道的程序不回调；没挂 http 就没有地方收回调。
 181      if (spec.channels.length === 0 || this.app === undefined) return undefined;
 182  
 183      //M 最多等 startup_ms（和等就绪行一样长）；监听上了 address() 才有端口。
 184      const deadline = AbortSignal.timeout(spec.startupMs);
 185      let address = this.app.server.address();
 186      while (address === null) {
 187        //G 等太久就当这次启动失败，交给 Host 退避重试，不一直卡在启动中。
 188        if (deadline.aborted) throw new Error(`主服务一直没开始监听，拿不到回调地址（等了 ${String(spec.startupMs)} 毫秒）`);
 189  
 190        //M 每 100 毫秒看一次主服务监听上没有。
 191        await timers.setTimeout(100, undefined, { signal });
 192        address = this.app.server.address();
 193      }
 194  
 195      //G 监听在管道上（不会这样配）就没有可回调的端口。
 196      if (typeof address === 'string') return undefined;
 197  
 198      //M 主服务监听全部地址（0.0.0.0、::）时程序走本机回环，本机来的请求 http 插件不查主令牌。
 199      let host = address.address;
 200      if (host === '0.0.0.0' || host === '::') host = '127.0.0.1';
 201      if (host.includes(':')) host = `[${host}]`;
 202      return `http://${host}:${String(address.port)}/api/programs/${spec.name}`;
 203    }
```

### 解释
- Host L380–L383：新密钥放进子进程环境 `JMBOTS_PROGRAM_KEY`，先删掉旧的回调变量。
- Host L385–L389：向 ChannelBridge 要回调前缀，放进 `JMBOTS_CALLBACK_URL`。
- ChannelBridge L179–L203：
  - 没登记渠道或没挂 http 就不给；
  - 等主服务监听上，取端口，拼成 `http://127.0.0.1:端口/api/programs/<名字>`。

