```ts
// src7/plugins/programs/Protocol.ts
 196  function parseReady(line: string, spec: ProgramSpec): ReadyLine | undefined {
 197    let decoded: unknown;
 198    try {
 199      decoded = JSON.parse(line);
 200    } catch {
 201      return undefined;
 202    }
 203    if (typeof decoded !== 'object' || decoded === null) return undefined;
 204  
 205    const raw = decoded as Record<string, unknown>;
 206    const protocol = raw['jmbots'];
 207    if (typeof protocol !== 'number') return undefined;
 208  
 209    //G 版本不兼容时阻止自动重试，等用户换正确的程序。
 210    if (protocol !== PROTOCOL) {
 211      throw new UnsupportedProtocol(`协议版本不对（程序 ${String(protocol)}，jmbots 支持 ${String(PROTOCOL)}）`);
 212    }
 213    if (raw['event'] !== 'ready' || raw['name'] !== spec.name) {
 214      throw new Error(`就绪行的事件或程序名和 ${spec.name} 不符`);
 215    }
 216    const version = raw['version'];
 217    if (typeof version !== 'string' || version.trim() === '') throw new Error('就绪行缺少程序版本');
 218  
 219    const port = raw['port'];
 220    if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535) {
 221      throw new Error('就绪行端口要是 1 至 65535 的整数');
 222    }
 223    if (spec.port !== 0 && port !== spec.port) throw new Error(`就绪行端口与配置 ${String(spec.port)} 不符`);
 224  
 225    return { version, port };
 226  }
```

### 解释
- Host L425：`waitReady` 等就绪行，超过 `startup_ms` 就算启动失败。
- Protocol L206–L212：协议版本不对抛 `UnsupportedProtocol`，状态改 blocked，不再自动重试。
- Protocol L213–L223：
  - 事件不是 ready、名字不符，抛错；
  - 缺版本，抛错；
  - 端口不合法，或和配置的固定端口不同，抛错。

