// src7/plugins/programs/Protocol.ts
 275  export async function readReport(
 276    url: string, name: string, route: 'info' | 'health', timeoutMs: number, signal: AbortSignal,
 277  ): Promise<ProgramReport | undefined> {
 278    const endpoint = `${url}/jmbots/v1/${route}`;
 279    const timeout = AbortSignal.timeout(timeoutMs);
 280    const until = AbortSignal.any([signal, timeout]);
 281    const options: RequestInit = { signal: until, redirect: 'error' };
 282    try {
 283      //M 只信已核对协议与程序名的回执，不让错误服务提供资源排行或暂停能力。
 284      const response = await fetch(endpoint, options);
 285      const decoded: unknown = await response.json();
 286      if (!response.ok || typeof decoded !== 'object' || decoded === null) return undefined;
 287  
 288      const raw = decoded as Record<string, unknown>;
 289      if (raw['ok'] !== true || raw['protocol'] !== PROTOCOL || raw['name'] !== name) return undefined;
 290  
 291      const capabilities = raw['capabilities'];
 292      const pause = Array.isArray(capabilities) && capabilities.includes('pause');
 293      let rssMb: number | undefined;
 294      const rss = raw['rssMb'];
 295      if (typeof rss === 'number' && Number.isFinite(rss) && rss >= 0) {
 296        rssMb = rss;
 297      }
 298      //M 界面只接受程序内部路径，不接受任意主机、端口或脚本URL。
 299      const ui = getUiPath(raw['ui']);
 300      return { pause, rssMb, ui };
 301    } catch {
 302      return undefined;
 303    }
 304  }
```

