// src7/plugins/programs/Host.ts
 497    /** 定期核对活着的程序，达连续失败阈值后交给监督任务重启。 */
 498    private async watchHealth(endpoint: string, signal: AbortSignal): Promise<void> {
 499      let misses = 0;
 500      let licenseAt = Date.now();
 501      const wait = { signal };
 502      while (!signal.aborted) {
 503        await timers.setTimeout(this.timing.watchMs, undefined, wait);
 504  
 505        //M 独立探测健康接口，连接失败与身份不符都算一次失败。
 506        const report = await protocolModule.readReport(
 507          endpoint, this.spec.name, 'health', this.timing.healthMs, signal,
 508        );
 509        signal.throwIfAborted();
 510        if (report !== undefined) {
 511          this.rssMb = report.rssMb;
 512          this.rssAt = Date.now();
 513          if (Date.now() - licenseAt >= 60_000) {
 514            //M 每分钟更新一次授权，缺接口或失败保持未知，不把未知当未授权。
 515            this.license = await protocolModule.readLicense(endpoint, signal);
 516            signal.throwIfAborted();
 517            licenseAt = Date.now();
 518            //M 授权状态变化单独广播，不把授权到期当停机。
 519            this.publishState();
 520          }
 521          misses = 0;
 522          this.note = '在运行';
 523          continue;
 524        }
 525        misses += 1;
 526        this.note = `健康检查连续失败 ${String(misses)} 次`;
 527        if (misses >= this.timing.healthMisses) {
 528          this.state = 'unhealthy';
 529          //M 健康异常不再提供ready入口，后续正常停止/重试由监督处理。
 530          this.publishState();
 531          return;
 532        }
 533      }
 534    }
